import numpy as np

def checks(close):
    """Panel checks: shape, NaN count, all positive, formation starts at 1."""
    return {
        "shape": close.shape,
        "nan": int(np.isnan(close).sum()),
        "positive": bool((close > 0).all()),
        "starts_at_one": bool(np.allclose(normalise(close[:252])[0], 1.0)),
    }

import numpy as np

def placebo_pairs(Pn_form, Pn_trade, k, seed):
    """Mean payoff of k random pairs, no wait."""
    rng = np.random.default_rng(seed)
    N = Pn_form.shape[1]
    payoffs = []
    for _ in range(k):
        i, j = rng.choice(N, 2, replace=False)
        payoffs.append(trade_pair(Pn_form, Pn_trade, int(i), int(j))[0])
    return float(np.mean(payoffs))
